-- InvoiceDesk 07: small summary tables behind the README charts (run after 06)
\copy (SELECT severity, check_name, COUNT(*) AS exceptions FROM exception_report GROUP BY 1, 2 ORDER BY 3 DESC) TO 'outputs/exceptions_by_check.csv' CSV HEADER
\copy (SELECT status, COUNT(*) AS invoices, ROUND(SUM(tax), 2) AS tax_in_books FROM gst_2b_match GROUP BY 1 ORDER BY 2 DESC) TO 'outputs/gst_2b_summary.csv' CSV HEADER
\copy (SELECT status, COUNT(*) AS invoices, ROUND(SUM(total_amount), 2) AS invoice_value FROM payment_match GROUP BY 1 ORDER BY 2 DESC) TO 'outputs/payment_summary.csv' CSV HEADER
\copy (SELECT v.vendor_name, COUNT(*) AS invoices, ROUND(SUM(m.tax), 2) AS tax_at_risk FROM gst_2b_match m JOIN vendor_master v USING (vendor_id) WHERE m.status = 'MISSING_IN_2B' GROUP BY 1 ORDER BY 3 DESC) TO 'outputs/missing_2b_by_supplier.csv' CSV HEADER
\copy (SELECT * FROM (VALUES ('Duplicate invoices (caught before payment)', (SELECT SUM(total_amount) FROM pr_flags WHERE is_duplicate)), ('Unpaid past due date', (SELECT SUM(total_amount) FROM payment_match WHERE status = 'UNPAID_OVERDUE')), ('Paid twice (extra payment)', (SELECT SUM((paid + tds) / n) FROM payment_match WHERE status = 'PAID_TWICE')), ('GST credit at risk (missing in 2B)', (SELECT SUM(tax) FROM gst_2b_match WHERE status = 'MISSING_IN_2B')), ('Underpaid (short)', (SELECT SUM(total_amount - paid - tds) FROM payment_match WHERE status = 'UNDERPAID')), ('TDS not deducted', (SELECT SUM(r.taxable_value * 0.10) FROM payment_checks c JOIN payments p USING (payment_id) JOIN purchase_register r ON r.vendor_id = p.vendor_id AND r.invoice_no = p.invoice_no WHERE c.check_name = 'TDS_NOT_DEDUCTED')), ('Overpaid (excess)', (SELECT SUM(paid + tds - total_amount) FROM payment_match WHERE status = 'OVERPAID'))) t(issue, amount_rs)) TO 'outputs/money_at_risk.csv' CSV HEADER
